rules.bad:
# Dockerfile —— 把生产配置打进镜像，同一个 tag 在不同环境是两份不同的东西
COPY target/classes/application-prod.yml ./config/
ENTRYPOINT [ "java", "-jar", "app.jar", "--spring.profiles.active=prod" ]

// 兜底值里写死生产地址：忘了配 env 时它会静默连到生产
@Value("${spring.datasource.url:jdbc:mysql://prod-db.internal:3306/app}")
private String url;

// 多副本下会被执行 N 次 —— N 等于 replicas，且不报错
@Scheduled(cron = "0 0/5 * * * ?")
public void syncOrders() {
    List<Order> pending = orderMapper.selectPending();
    for (Order o : pending) {
        remote.push(o);      // 每个副本都推一遍
        orderMapper.markSynced(o.getId());
    }
}

rules.good:
// 方案一：持分布式锁，谁拿到谁跑（ShedLock）
@Scheduled(cron = "0 0/5 * * * ?")
@SchedulerLock(name = "syncOrders", lockAtMostFor = "4m", lockAtLeastFor = "1m")
public void syncOrders() {
    orderMapper.selectPending().forEach(this::pushOnce);
}

// 方案二：把触发权交给调度中心（XXL-Job），应用只负责执行
@XxlJob("syncOrders")
public void syncOrders() {
    orderMapper.selectPending().forEach(this::pushOnce);
}

// 无论哪种，处理逻辑本身要幂等 —— 锁只降低并发概率，不能消除重复投递
private void pushOnce(Order o) {
    if (!stateService.tryClaim(o.getId())) return;
    remote.push(o);
}

rules.bad:
// ① 会话放进程内存：Pod 重启就要全员重新登录
@PostMapping("/login")
public void login(HttpSession session, LoginCmd cmd) {
    session.setAttribute("userId", cmd.getUserId());
}

// ② 上传文件写容器本地盘：容器文件系统随容器一起消失
public String save(MultipartFile file) throws Exception {
    Path p = Paths.get("/app/upload/" + file.getOriginalFilename());
    file.transferTo(p);
    return p.toString();
}

rules.good:
// ① 会话进 Redis —— 实例被替换不影响登录态
@PostMapping("/login")
public void login(LoginCmd cmd, HttpServletResponse resp) {
    String token = tokenService.issue(cmd.getUserId());
    resp.setHeader(HttpHeaders.AUTHORIZATION, "Bearer " + token);
}

// ② 上传文件进对象存储，库里只留 key
public String save(MultipartFile file) throws Exception {
    String key = "upload/" + UUID.randomUUID() + suffixOf(file);
    objectStorage.put(key, file.getInputStream());
    return key;
}

rules.bad:
management:
  endpoint:
    health:
      probes:
        enabled: false
  health:
    # 数据库也算进默认健康判定的结果里
    defaults: on

# 自定义 liveness 里直接查库 —— 库抖一下，全集群一起重启
@RestController
class Probe {
    @GetMapping("/live")
    boolean live() { return jdbc.execute("select 1") == 1; }
}

rules.good:
management:
  endpoint:
    health:
      probes:
        enabled: true        # 分出 liveness / readiness 两个健康组

# readiness：不就绪就摘流量，允许含轻量依赖的组
readinessProbe:
  httpGet: { path: /actuator/health/readiness, port: 8080 }
# liveness：只反映进程自身，绝不带下游
livenessProbe:
  httpGet: { path: /actuator/health/liveness, port: 8080 }

# 确实需要表达「下游不通」时，用就绪态而不是重启：
@Component
class CacheHealthIndicator implements HealthIndicator {
    public Health health() {
        return cacheReachable ? Health.up().build() : Health.down().build();
    }
}
